
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _needAnti:true,
    },

    // LIFE-CYCLE CALLBACKS:

    //初始化
    Init:function(){
        this._topAniNode = cc.find("top_ani",this.node)

        this._topScript = cc.vv.gameData.GetTopScript()
        this._bottomScript = cc.vv.gameData.GetBottomScript()

        this._cfg = cc.vv.gameData.getGameCfg()
        this._col = 15
        this._row = 1

        this.createReels(this._col,this._row)

        this._bottomScript.ShowBtnsByState("idle")


        // this.RegisterEvent()

        //断线重连的显示
        // this.ReconnectShow()

        //初始化奖池
        // this.CheckJoopLock()
    },

    //创建卷轴
    createReels:function(col,row){
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this.node)
            let scp = node.addComponent("Loki_BonusReel")
            scp.Init(i,row,this._topAniNode)
            this._reels.push(scp)

        }
    },


    //点击旋转按钮调用
    StartMove:function(bonusItems){
        this._bStopRightnow = null
        this._gameInfo = null
        this._bonusGame = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        let reels = [];
        let idxs = [];
        this._moveIdxs = []
        bonusItems.forEach(item=>{
            idxs.push(item.idx-1);
        })
        this._reels.forEach(reel=>{
            if(!idxs.includes(reel.GetReelIdx())){
                reels.push(reel)
                this._moveIdxs.push(reel.GetReelIdx())
            }
        })

        //每列转起来
        this.MoveReels(reels)
        this.setMoveLastIdx(this._moveIdxs);

        this._moveIdxs.sort((a,b)=>{
            return a / 5 - b / 5
        }).sort(function (a, b) {
            return a % 5 - b % 5
        });

        cc.log(this._moveIdxs);

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()
    },


    setMoveLastIdx(reelIdxs){
        let max = reelIdxs[0];
        let reelMax= [];
        reelIdxs.forEach(idx=>{
            if(idx%5 > max%5 || (idx%5 == max%5 && idx/3 > max/3)){
                max = idx;
            }

            reelMax[idx%5] = reelMax[idx%5] ? Math.max(reelMax[idx%5], idx) : idx;
        });
        this.moveReelLastIdx = max;
        cc.log("StartMove：this.moveReelLastIdx:",this.moveReelLastIdx);
        this._reelMax = reelMax;
        cc.log(this._reelMax)
    },


    //重写 每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        if(!this._needAnti){
            let nIter = this._cfg.reelStopInter || 0.6
            return (reelIdx%5) *nIter;
        }
        else {
            let nIter = 0.6
            let idx = this._moveIdxs.indexOf(reelIdx)

            let addT = 0;
            if(this._needAnti){
                addT = cc.vv.gameData.getGameCfg().AddAntiTime || 1
            }
            return idx*nIter+addT
        }
    },

    // onMsgSpine:function(msg){
    //     cc.log(msg)
    //
    //     this._gameInfo = msg
    //     let cards = msg.resultCards
    //
    //     this.SetSlotsResult(cards)
    //     // this.SetReelStateInfo(cards)
    //
    // },

    setSpinResult(msg){
        this._bonusGame = msg;

        let cards = [];
        let dataList = [];
        this._bonusGame.bonusItems.forEach(item=>{
            dataList[item.idx-1] = item;
            cards[item.idx-1] = 3;
        })
        for (let i = 0; i < 15; i++){
            if(!cards[i]){
                cards[i] = this.GetSymbolByIdx(1).getRandomSymbol();
            }
        }

        this.SetReelStateInfo();

        this.SetSlotsResult(cards, dataList);

    },

    SetSlotsResult:function(cards, dataList){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = dataList[i];
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    SetReelStateInfo(){
        if(this._bonusGame.spinCnt == 0 && this._bonusGame.jackpot.restCnt == 1){
            this._needAnti = true;
        } else {
            this._needAnti = false;
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isAnt = this._needAnti;

            for (let i = 0; i < this._moveIdxs.length; i++){
                let item = this._reels[this._moveIdxs[i]];

                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }

        if(!this._bStopRightnow && this._needAnti){
            this._reels[this._moveIdxs[0]].playAntiAnimation(true);
        }
    },

    //回弹动作之前
    OnReelBounsActionBefore:function(colIdx){
        //检查免费加速
        this.DoCheckReelAnti(colIdx)
    },

    //回弹动作最低点
    OnReelBounsActionDeep(colIdx){
        if(this._reels[colIdx].GetSymbolByRow(0).GetShowId() === 3){
            this._reels[colIdx].GetSymbolByRow(0).playStopAnimation();
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_bonus_down");
        }

        if(colIdx == this._reelMax[colIdx%5]){
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_reel_down");
        }
    },

    //配置了加速节点才显示，如果点击了立即停止(_bStopRightnow)也不显示了。
    //每列停止后，会自动隐藏加速节点
    DoCheckReelAnti:function(colIdx){
        if(!this._bStopRightnow && this._needAnti){
            let isPlayAnit = false
            for(let i = 0; i < this._moveIdxs.length; i++){
                let idx = this._moveIdxs[i];
                if(i == this._moveIdxs.indexOf(colIdx)+1){
                    isPlayAnit = this._reels[idx].playAntiAnimation()
                }
                if(i > this._moveIdxs.indexOf(colIdx) && isPlayAnit){
                    let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                    this._reels[idx].AddDelayTime(nAddSpeedTime)
                }
            }
        }
    },

    //重写spin end
    async OnSpinEnd(){
        // 图标显示到上层


        // this.CanDoNextRound();
    },


    // 初始显示所有的图标
    initAllSymbol(items, cards){
        let dataList = [];
        for (let i = 0; i < items.length; i++){
            dataList[items[i].idx-1] = items[i];
        }

        for (let i = 0; i < 15; i++){
            let symbol = this.GetSymbolByIdx(i+1);
            symbol.setSymbolMask(false);
            let data = dataList[i];
            if(cards){
                symbol.ShowById(cards[i], data);
            } else {
                if(data){
                    symbol.ShowById(3, data);
                } else {
                    symbol.ShowById(symbol.getRandomSymbol(), data);
                }
            }
        }
    },

    CanStopSlot(){
        return this._bonusGame != null
    },

    // update (dt) {},
});
