

cc.Class({
    extends: cc.Component,

    properties: {
        _moreAward:[],  // 赢奖池最低个数
        _curCnt:0,  // 总共个数

    },

    // LIFE-CYCLE CALLBACKS:

    Init(){
        this._bonus_bg = cc.find("safe_node/spr_bg_free", this.node);
        this._bonus_bg.active = false;

        this._normal_slots = cc.find("safe_node/slots/reels", this.node);
        this._bonus_slots = cc.find("safe_node/slots/bonusGame", this.node);
        this._bonus_slots.active = false;
        this._slotsScript = this._bonus_slots.addComponent("Loki_BonusSlots");
        this._slotsScript.Init();

        this._node_remainTimes = cc.find("safe_node/slots/bonus_remainTimes", this.node);
        this._node_remainTimes.active = false;
        this._anim_reset = cc.find("anim_reset", this._node_remainTimes);
        this._anim_reset.active = false;

        this._node_count = cc.find("safe_node/bonus_cnt", this.node);
        this._node_count.active = false;

        this._moreAward = [12,13,14,15];
    },

    //
    enterBonusGame(){
        return new Promise(async (success, failed)=> {
            cc.vv.gameData.getCollectScript().setCollectNodeState(false);

            cc.vv.gameData.setIsBonusGame(true);
            Global.SlotsSoundMgr.playBgm("music_Atlantis_respin");

            this._bonus_bg.active = true;
            this._bonus_slots.active = true;
            this._normal_slots.active = false;

            this._bonusGame = cc.vv.gameData.getBonusGame()
            this.lockJackpot(this._bonusGame.jackpotValues)
            this.initBonusSlots();

            this.showRemainTime(this._bonusGame.spinCnt, true);

            this._jackpot = this._bonusGame.jackpot;
            this.showBonusCnt(this._jackpot);

            await cc.vv.gameData.awaitTime(2);
            this.reqSpine();

            this._bonusSuccess = success;
            // success();
        });
    },

    exitBonusGame(){
        /*let pos = this._node_count.position;
        cc.tween(this._node_count)
            .to(0.5, {position:cc.find("safe_node/slots/reels", this.node).position})
            .call(()=>{
                this._node_count.active = false;
                this._node_count.position = pos;
            })
            .start()*/

        this._node_remainTimes.active = false;

        cc.vv.gameData.setIsBonusGame(false);
        // this.resetJackpot()

        // this._bonus_slots.active = false;
        // this._normal_slots.active = true;
        // this.copyAllSymbol();

        if(this._bonusSuccess){
            this._bonusSuccess();
            this._bonusSuccess = null;
        }
    },

    showNormalSlots(){
        this._bonus_slots.active = false;
        this._normal_slots.active = true;
        this.copyAllSymbol();
    },

    copyAllSymbol(){
        for (let i = 1; i <= 15; i++){
            let symFrom = this._slotsScript.GetSymbolByIdx(i);
            let symTo =  cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(i);

            symTo.ShowById(symFrom.GetShowId(), symFrom.GetData());
        }
    },

    // bonus游戏旋转结果请求
    async reqSpine(){
        // this._curCnt

        this.showRemainTime(this._bonusGame.spinCnt-1, false);
        this._slotsScript.StartMove(this._bonusGame.bonusItems);
        await cc.vv.gameData.awaitTime(1);
        let reqdata = {rtype:1};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._bonusGame = result.data.bonusGame;
            cc.vv.gameData.setBonusGame(this._bonusGame);
            this._slotsScript.setSpinResult(this._bonusGame);
        }

    },


    GetLastStopReelIdx(){
        return this._slotsScript.GetLastStopReelIdx();
    },

    StartMove(){
        this._slotsScript.StartMove(this._bonusGame.bonusItems);
    },

    StopMove(){
        this._slotsScript.StopMove();
    },

    // onMsgSpine(msg){
    //     this._bonusGame = msg.bonusGame;
    //
    //     this._slotsScript.onMsgSpine(msg);
    // },

    OnReelReadyToStop(colIdx){
        this._slotsScript.OnReelReadyToStop(colIdx);
    },

    OnReelBounsActionBefore(colIdx){
        this._slotsScript.OnReelBounsActionBefore(colIdx);
    },

    OnReelBounsActionDeep(colIdx){
        this._slotsScript.OnReelBounsActionDeep(colIdx);
    },

    OnReelBounsActionEnd(colIdx){
        this._slotsScript.OnReelBounsActionEnd(colIdx);
    },

    async OnSpinEnd(){
        // this._slotsScript.OnSpinEnd();

        // 发生改变
        this.showRemainTime(this._bonusGame.spinCnt, false);
        this.showBonusCnt(this._bonusGame.jackpot);



        // let triJp, isEnd;
        // if(this._bonusGame.winCoin > 0){
        //     await cc.vv.gameData.showWinJp(winCoin, jpType);
        // }

        if(this._bonusGame.state == 2){
            if(this._bonusGame.winCoin > 0){
                await cc.vv.gameData.getPopupScript().showWinJp(this._bonusGame.winCoin, this._bonusGame.jackpot.currJackpotId);
                cc.vv.gameData.AddCoin(this._bonusGame.winCoin);
                await new Promise((success, failed)=>{
                    this._slotsScript.ShowBottomWin(this._bonusGame.winCoin,this._bonusGame.winCoin,true,success)
                });
            }

            cc.vv.gameData.SetFreeTime(this._bonusGame.jackpot.currCnt);
            cc.vv.gameData.SetTotalFree(this._bonusGame.jackpot.currCnt);

            // await cc.vv.gameData.getFreeScript().triFreeGame();
            this.exitBonusGame();
        }/*else if(isEnd){
            // await cc.vv.gameData.getFreeScript().triFreeGame();

            this.exitBonusGame();
        }*/ else {

            await cc.vv.gameData.awaitTime(0.5);
            this.reqSpine()
        }

        // cc.vv.gameData.GetSlotsScript().CanDoNextRound();

    },

    initBonusSlots(){
        this._gameInfo = cc.vv.gameData.getGameInfo();
        let cards = null;
        if(this._gameInfo){
            cards = this._gameInfo.resultCards
        }
        this._slotsScript.initAllSymbol(this._bonusGame.bonusItems,cards);
    },


    showRemainTime(cnt, init){
        this._node_remainTimes.active = true;

        cc.find("lbl", this._node_remainTimes).getComponent(cc.Label).string = cnt;
        if(cnt === 3 && !init){
            this._anim_reset.active = true;
            this._anim_reset.getComponent(cc.Animation).play("spins_reset");
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_bonus_add");
        }
    },

    showBonusCnt(jackpot){
        this._node_count.active = true;

        cc.find("lbl_cnt",this._node_count).getComponent(cc.Label).string = jackpot.currCnt;
        cc.find("lbl_more",this._node_count).getComponent(cc.Label).string = jackpot.restCnt;
        let jpName = ["mini", "minor", "major", "grand"];
        cc.find("spr_jp",this._node_count).getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("baseImg").getSpriteFrame(cc.js.formatStr("jp_%s_1", jpName[jackpot.nextJackpotId-1]));


        // this._curCnt = cnt;
    },



    GetSymbolByIdx(idx){
        return this._slotsScript.GetSymbolByIdx(idx)
    },

    //奖池锁定(停止滚动)
    lockJackpot(poolList){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:poolList[0]},{prizeType:1,pauseNum:poolList[1]},
            {prizeType:2,pauseNum:poolList[2]},{prizeType:3,pauseNum:poolList[3]}]);
    },

    //复位奖池(继续滚动)
    resetJackpot(){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.ResumePausePool();
    },

    // update (dt) {},
});
