
cc.Class({
    extends: cc.Component,

    properties: {
        _itemList:[],
    },

    Init(){
        this._collect_node = cc.find("safe_node/slots/node_collect", this.node);

        for (let i = 1; i <= 10; i++){
            let item = cc.find("list/item"+i, this._collect_node);
            cc.find("spr", item).active = false;
            cc.find("anim_show", item).active = false;
            this._itemList[i]=item;
        }

        this._spr_light = cc.find("spr_light", this._collect_node);
        this._spr_light.active = false;

        this._spr_super = cc.find("spr_super", this._collect_node);
        this._super_sg = cc.find("anim", this._spr_super);
        this._super_sg.active = false;

        this._jdt_sg = cc.find("anim_sg", this._collect_node);
        this._jdt_sg.active = false;

        this._btn_tip = cc.find("btn_tip", this._collect_node);
        Global.btnClickEvent(this._btn_tip, this.onClickTipBtn, this);
        this._spr_tip = cc.find("spr_tip", this._collect_node);
        this._spr_tip.active = false;

        this._bonusTrail = cc.vv.gameData.getBonusTrail();
        this.initItems();
    },

    setCollectNodeState(bShow){
        this._collect_node.active = bShow;
    },

    initItems(){
        let curCnt = cc.vv.gameData.getBonusTrail().count;

        for (let i = 1; i < this._itemList.length; i++){
            cc.find("spr", this._itemList[i]).active = curCnt >= i;
        }
    },

    addItem(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_colloct");

            this._bonusTrail = cc.vv.gameData.getBonusTrail();
            let curCnt = this._bonusTrail.count;

            let spr = cc.find("spr", this._itemList[curCnt]);
            spr.active = true;
            spr.setScale(0);
            cc.tween(spr).to(0.5, {scale: 1}).start();

            await cc.vv.gameData.awaitTime(0.4);
            let animNode = cc.find("anim_show", this._itemList[curCnt]);
            animNode.active = true;
            let anim = animNode.getComponent(cc.Animation)
            anim.play("jdt_itemShow");
            anim.on("stop", ()=>{
                animNode.active = false;
                success();
            })
        });
    },

    fullAnim(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_superFs_trigger");
            this._jdt_sg.active = true;
            this._jdt_sg.getComponent(cc.Animation).play("jdt_saoguang");

            await cc.vv.gameData.awaitTime(0.5);
            this._super_sg.active = true;
            this._super_sg.getComponent(cc.Animation).play("jdt_super");

            await cc.vv.gameData.awaitTime(0.5);
            this._spr_light.active = true;
            this._spr_light.stopAllActions();
            cc.tween(this._spr_light).repeatForever(cc.tween().by(2, {angle:-360})).start();

            cc.tween(this._spr_super)
                .to(0.5, {scale:1.3})
                .to(0.8, {scale:0.8})
                .to(0.3, {scale:1})
                .call(()=>{
                    this._spr_light.stopAllActions();
                    this._spr_light.active = false;
                    success();
                })
                .start()
        });
    },

    onClickTipBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;

        this._spr_tip.stopAllActions();
        if(this._spr_tip.active){
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(this._spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        } else {
            this._spr_tip.active = true;
            this._spr_tip.setScale(0);
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(3),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        }
    },

    // update (dt) {},
});
