
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_popup = cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;
        this._node_free_tri = cc.find("node_free_tri",this._node_popup);
        this._node_free_end = cc.find("node_free_end",this._node_popup);
        this._node_jp_win = cc.find("node_jp_win",this._node_popup);
        this._node_free_tri.active = false;
        this._node_free_end.active = false;
        this._node_jp_win.active = false;

        this._node_qp1 = cc.find("safe_node/node_qp1", this.node);
        this._node_qp1.active = false;
    },



    // 赢得免费
    showTriFree(cnt){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_show_freespin_start");
            this._node_popup.active = true;
            this._node_free_tri.active = true;

            let node_qiu = cc.find("node_qiu", this._node_free_tri);
            let spr_free = cc.find("spr_free", this._node_free_tri);
            let spr_super = cc.find("spr_super", this._node_free_tri);
            cc.find("lbl_cnt", node_qiu).getComponent(cc.Label).string = cnt;

            spr_free.active = !cc.vv.gameData.isSuperBonus();
            spr_super.active = cc.vv.gameData.isSuperBonus();

            node_qiu.setScale(0);
            spr_free.setScale(0);
            spr_super.setScale(0);
            cc.tween(node_qiu).to(0.5, {scale:1}, {easing:"backOut"}).start();
            cc.tween(spr_free).delay(0.2).to(0.5, {scale:1}, {easing:"backOut"}).start();
            cc.tween(spr_super).delay(0.2).to(0.5, {scale:1}, {easing:"backOut"}).start();

            await cc.vv.gameData.awaitTime(2.5);
            cc.tween(spr_free).to(0.5, {scale:0}, {easing:"backIn"}).start();
            cc.tween(spr_super).to(0.5, {scale:0}, {easing:"backIn"}).start();
            cc.tween(node_qiu).delay(0.2).to(0.5, {scale:0}, {easing:"backIn"}).start();

            await cc.vv.gameData.awaitTime(0.7);
            this._node_popup.active = false;
            this._node_free_tri.active = false;
            success();
        })
    },

    // 免费结束
    showEndFree(winCoin){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_show_freespin_over");
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_popup.active = true;
            this._node_free_end.active = true;

            let bg = cc.find("bg", this._node_free_end);
            let light = cc.find("light", this._node_free_end);
            let par = cc.find("par", this._node_free_end);
            let spr1 = cc.find("spr1", this._node_free_end);
            let spr2 = cc.find("spr2", this._node_free_end);
            let spr_kuang = cc.find("spr_kuang", this._node_free_end);
            let spr3 = cc.find("spr3", this._node_free_end);
            let spr_cnt = cc.find("spr_cnt", this._node_free_end);
            let spr_cnt_super = cc.find("spr_cnt_super", this._node_free_end);
            let btn_collect = cc.find("btn_collect", this._node_free_end);
            btn_collect.getComponent(cc.Button).interactable = false;

            let lbl_winCoin = cc.find("spr_kuang/lbl_wincoin", this._node_free_end);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 1.5,null,null,0,true);

            cc.find("lbl_cnt", spr_cnt).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            cc.find("lbl_cnt", spr_cnt_super).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();

            bg.opacity = 0;
            light.opacity = 0;
            spr1.opacity = 0;
            spr2.opacity = 0;
            spr_kuang.opacity = 0;
            spr3.opacity = 0;
            spr_cnt.opacity = 0;
            btn_collect.opacity = 0;
            bg.setScale(0);
            light.setScale(0);
            spr1.setScale(0);
            spr2.setScale(0);
            spr_kuang.setScale(0);
            spr3.setScale(0);
            spr_cnt.setScale(0);
            btn_collect.setScale(0);

            spr_cnt.active = !cc.vv.gameData.isSuperBonus();
            spr_cnt_super.active = cc.vv.gameData.isSuperBonus();

            let scaleTime = 0.3;
            let delayTime = 0.1;
            cc.tween(bg).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(light).delay(delayTime).to(scaleTime, {scale:1.5,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr1).delay(delayTime*2).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr2).delay(delayTime*3).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr_kuang).delay(delayTime*4).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr3).delay(delayTime*5).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr_cnt).delay(delayTime*5).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(spr_cnt_super).delay(delayTime*5).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()
            cc.tween(btn_collect).delay(delayTime*7).to(scaleTime, {scale:1,opacity:255}, {easing:"backOut"}).start()

            cc.tween(light).repeatForever(cc.tween().by(3,{angle:-360})).start()
            await cc.vv.gameData.awaitTime(delayTime*7+scaleTime);

            par.active = true;
            par.getComponent(cc.ParticleSystem).resetSystem();

            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            let self = this;

            let clickFunc = async()=> {
                btn_collect.getComponent(cc.Button).interactable = false;
                if(Global.FormatCommaNumToNum(lbl_winCoin.getComponent(cc.Label).string) != winCoin){
                    lbl_winCoin.stopAllActions();
                    lbl_winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                    await cc.vv.gameData.awaitTime(0.1);
                }

                par.active = false;
                cc.tween(light).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr1).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr2).delay(delayTime).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr_kuang).delay(delayTime*2).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr3).delay(delayTime*3).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr_cnt).delay(delayTime*4).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(spr_cnt_super).delay(delayTime*4).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(btn_collect).delay(delayTime*4).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                cc.tween(bg).delay(delayTime*5).to(scaleTime, {scale:0,opacity:0}, {easing:"backIn"}).start()
                await cc.vv.gameData.awaitTime(delayTime*5+scaleTime);

                self._node_popup.active = false;
                self._node_free_end.active = false;

                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.on("click", async()=> {
                btn_collect.stopAllActions();
                clickFunc()
            });
        })
    },

    // 赢得奖池
    showWinJp(winCoin, jpType){
        return new Promise(async (success, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

            this._node_popup.active = true;
            this._node_jp_win.active = true;

            let bg = cc.find("bg", this._node_jp_win);
            let spr_jp = cc.find("spr_jp", this._node_jp_win);
            let spr_kuang = cc.find("spr_kuang", this._node_jp_win);
            let btn_collect = cc.find("btn_collect", this._node_jp_win);
            btn_collect.getComponent(cc.Button).interactable = false;

            let lbl_winCoin = cc.find("spr_kuang/lbl_wincoin", this._node_jp_win);

            Global.SlotsSoundMgr.playEffect("sound_Atlantis_JackPotWinCoins");
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 10,function () {
                Global.SlotsSoundMgr.playEffect("sound_Atlantis_JPCoinsJump_Over");
            },null,0,true);

            let jpName = ["mini", "minor", "major", "grand"]
            spr_jp.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("baseImg").getSpriteFrame(cc.js.formatStr("jp_%s_2",jpName[jpType-1]));

            bg.setScale(0);
            spr_jp.setScale(0);
            spr_kuang.setScale(0);
            btn_collect.setScale(0);

            let scaleTime = 0.5;
            let delayTime = 0.1;
            cc.tween(bg).to(scaleTime,{scale:1},{easing:"backOut"}).start()
            cc.tween(spr_jp).delay(delayTime).to(scaleTime,{scale:1},{easing:"backOut"}).start()
            cc.tween(spr_kuang).delay(delayTime*2).to(scaleTime,{scale:1},{easing:"backOut"}).start()
            cc.tween(btn_collect).delay(delayTime*3).to(scaleTime,{scale:1},{easing:"backOut"}).start()
            await cc.vv.gameData.awaitTime(delayTime*3+scaleTime);

            btn_collect.off("click");
            btn_collect.getComponent(cc.Button).interactable = true;
            let self = this;

            let clickFunc = async()=> {
                btn_collect.getComponent(cc.Button).interactable = false;
                if(Global.FormatCommaNumToNum(lbl_winCoin.getComponent(cc.Label).string) != winCoin){
                    Global.SlotsSoundMgr.stopEffectByName("sound_Atlantis_JackPotWinCoins");
                    lbl_winCoin.stopAllActions();
                    lbl_winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                    await cc.vv.gameData.awaitTime(0.1);
                }

                cc.tween(bg).to(scaleTime, {scale:0}, {easing:"backIn"}).start()
                cc.tween(spr_jp).delay(delayTime).to(scaleTime, {scale:0}, {easing:"backIn"}).start()
                cc.tween(spr_kuang).delay(delayTime*2).to(scaleTime, {scale:0}, {easing:"backIn"}).start()
                cc.tween(btn_collect).delay(delayTime*3).to(scaleTime, {scale:0}, {easing:"backIn"}).start()
                await cc.vv.gameData.awaitTime(delayTime*3+scaleTime);

                self._node_popup.active = false;
                self._node_jp_win.active = false;

                success();
            };
            cc.vv.gameData.checkAutoPlay(btn_collect, clickFunc);
            btn_collect.on("click", async()=> {
                btn_collect.stopAllActions();
                clickFunc();
            });
        })
    },


    // 清屏动画
    playQpAnim(){
        Global.SlotsSoundMgr.playEffect("sound_Atlantis_changeScene");

        this._node_qp1.active = true;

        let character = cc.find("character", this._node_qp1);
        character.active = true;
        character.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        character.getComponent(sp.Skeleton).setCompleteListener(()=>{
            character.getComponent(sp.Skeleton).setCompleteListener(null);
            character.active = false;
            this._node_qp1.active = false;
        })
    },

    // update (dt) {},
});
