
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:0,
    },

    setType(val){
        this._type = val;
    },


    ShowRandomSymbol(){
        let randVal
        let randomcfg = this.GetRandomCfg()
        if(randomcfg){
            let reelrandomCfg = randomcfg[this._reelIdx%5+1]
            if(reelrandomCfg){
                //gamedata中记录了当前列随机到符号表的序号了，只需要一个个往下随机就好
                let randIdx = cc.vv.gameData.GetReelRandomIdx(this._reelIdx%5)
                if(!cc.js.isNumber(randIdx)){
                    //如果没有就随机一个开始值，如果每次都从0开始，就每次进去游戏都是那几个图标
                    randIdx = Global.random(1,reelrandomCfg.length)-1
                }
                randVal = reelrandomCfg[randIdx]
                if(!randVal){ //如果取到最后了就从头开始取
                    randIdx = 0
                    randVal = reelrandomCfg[randIdx]
                }

                cc.vv.gameData.SetReelRandomIdx(this._reelIdx%5,++randIdx)
            }
        }
        else{//兼容旧的配置数据
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            randVal = cfg.randomSymbols[randIdx-1]
        }
        this.ShowById(randVal)

        if(this._id === 3){
            let num = Global.random(1,10)>9 ? 10 : Global.random(2,5);
            this.showMult(num);
        }
    },

    // 获得一个随机符号
    getRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomSymbols.length)
        return cfg.randomSymbols[randIdx-1]
    },

    //清除其他状态
    clearState:function(){
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    },

    StartMove() {
        this._super();

        if(this._type){
            this.setMaskVisible(true);
        }
    },

    setMaskVisible(bMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (bMask && cfg.symbol[this._id].isMask) {
                showNode.color = new cc.Color(100, 100, 100);
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },

    setSymbolMask(bMask){
        for (let i = 0; i < this.node.childrenCount; i++){
            if(bMask){
                this.node.children[i].color = new cc.Color(100, 100, 100);
            }else {
                this.node.children[i].color = cc.Color.WHITE;
            }
        }
    },

    ShowById:function(id,data){
        this._super(id,data);

        if(data && data.mult){
            this.showMult(data.mult);
        } else {
            this.showMult();
        }


        if(this._type){
            this.setMaskVisible(true);
        }
    },

    showMult(mult){
        let lbl_mult = cc.find("lbl_mult", this.node);
        let spr_freeSpin = cc.find("spr_freeSpin", this.node);
        if(mult){
            lbl_mult.active = true;
            lbl_mult.getComponent(cc.Label).string = mult+"X";
            spr_freeSpin.active = true;
        } else {
            lbl_mult.active = false;
            spr_freeSpin.active = false;
        }
    },

    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id === 3){
            let nScale = this._showNode.scale;
            this._showNodeOrgScale = nScale
            cc.tween(this._showNode).to(0.2, {scale:nScale+0.2}).to(0.1,{scale:nScale}).start()
            cc.tween(cc.find("lbl_mult",this.node)).to(0.2, {scale:1.2}).to(0.1,{scale:1}).start()
            cc.tween(cc.find("spr_freeSpin",this.node)).to(0.2, {scale:1.2}).to(0.1,{scale:1}).start()

            if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
                let winNode = cc.find(cfg.symbol[id].win_node, this.node);
                winNode.active = true;
                winNode.getComponent(cc.Animation).play(cfg.symbol[id].stop_ani.name);
                winNode.getComponent(cc.Animation).off("stop");
                winNode.getComponent(cc.Animation).on("stop",()=>{winNode.active = false});
            }

        }else {
            this._super();
        }
    },

    // update (dt) {},
});
