
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    Init(){
        this._spine_character = cc.find("Canvas/safe_node/character");

        this._super();
    },

    async ReconnectShow(){
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1");

        let bonusGame = cc.vv.gameData.getBonusGame();
        if(bonusGame){
            if(bonusGame.state == 1){
                await cc.vv.gameData.getBonusScript().enterBonusGame();

                // 触发免费
                if(cc.vv.gameData.GetTotalFree() > 0){
                    await this.triFreeGame();
                }
            } else if(bonusGame.state == 2){
                cc.vv.gameData.getBonusScript().lockJackpot(bonusGame.jackpotValues)
                this._spine_character.active = false;
                await cc.vv.gameData.getFreeScript().enterFreeGame();
                this.ShowGameview(true);
            }
        } else {
            this.ShowGameview(false);
        }

        this._topScript.StopMove();
        this._bottomScript.CanDoNextRound();
    },

    StartMove(){
        this._super();

        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusScript().StopMove();
        }else if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().StartMove();
        } else {
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    StopMove(){
        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusScript().StopMove();
        } else {
            this._super();
        }
    },

    onMsgSpine(msg){
        // if(cc.vv.gameData.isBonusGame()){
        //     cc.vv.gameData.getBonusScript().onMsgSpine(msg);
        // } else {
            this._super(msg);
        // }
    },

    SetSlotsResult:function(cards){
        let dataList = [];
        if(this._gameInfo.bonusItems && this._gameInfo.bonusItems.length > 0){
            for (let i = 0; i < this._gameInfo.bonusItems.length; i++){
                dataList[this._gameInfo.bonusItems[i].idx-1] = this._gameInfo.bonusItems[i];
            }
        }


        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = dataList[i];
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    OnSpinEnd(){
        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusScript().OnSpinEnd();

            // let isEnd;
            // if(isEnd){
            //     this.triFreeGame();
            // }
        } else if(cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getFreeScript().OnSpinEnd();

        } else {
            this.onSpinEndAction();
        }
    },

    async onSpinEndAction(){
        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise((success, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,success)
        });


        let isBonus, isFree, isEndFree;
        // 触发bonus
        if(this._gameInfo.bonusGame){
            let trail = this._gameInfo.bonusTrail
            if(trail.count == trail.totalCount){
                cc.vv.gameData.setIsSuperBonus(true)
            }

            await this.triBonusGame();
        }

        // 触发免费
        if(cc.vv.gameData.GetTotalFree() > 0){
            await this.triFreeGame();

        }

        // 结束免费
        if(isEndFree){

        }


        this.CanDoNextRound();
    },


    triBonusGame(){
        return new Promise(async (success, failed)=> {
            await cc.vv.gameData.getCollectScript().addItem();
            if(cc.vv.gameData.isSuperBonus()){
                await cc.vv.gameData.getCollectScript().fullAnim();
            }
            await cc.vv.gameData.awaitTime(1);

            cc.vv.gameData.getPopupScript().playQpAnim();

            await cc.vv.gameData.awaitTime(1);


            for (let i = 1; i <= 15; i++){
                this.GetSymbolByIdx(i).clearState()
            }

            await cc.vv.gameData.getBonusScript().enterBonusGame();



            success();
        });
    },

    triFreeGame(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_notice");
            cc.tween(this._spine_character).to(1, {opacity:0}).start();

            // this._spine_character.getComponent(sp.Skeleton).setAnimation(0, "upReel", false);
            // let entry = this._spine_character.getComponent(sp.Skeleton).addAnimation(0, "down", false);
            // this._spine_character.getComponent(sp.Skeleton).setTrackCompleteListener(entry, ()=>{this._spine_character.active = false;})

            let node_count = cc.find("bonus_cnt", this.node.parent);
            let node_items = cc.find("free_items", this.node);

            let pos_reel = cc.find("reels", this.node).position;
            let pos1 = node_count.position;
            let pos2 = node_items.position;
            node_items.position = pos_reel;

            cc.vv.gameData.getFreeScript().playFreeWin(0);
            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(node_count)
                .to(0.8, {position:pos_reel})
                .call(()=>{
                    node_count.active = false;
                    node_count.position = pos1;
                })
                .start()

            Global.SlotsSoundMgr.playEffect("sound_Atlantis_chessboard_up");
            node_items.active = true;
            cc.tween(node_items).to(0.8, {position:pos2}).start()


            await cc.vv.gameData.getFreeScript().triFreeGame();

            success();
        });
    },


    // 初始显示所有的图标
    initAllSymbol(cards, data){
        for (let i = 1; i <= 15; i++){

            this.GetSymbolByIdx(i).ShowById(cards[i], data)
        }
    },

    ShowGameview(bFree){
        this._super(bFree);

        cc.vv.gameData.setIsFreeGame(bFree);

        if(bFree){
            Global.SlotsSoundMgr.playBgm("music_Atlantis_freeGame");
        } else {
            this._spine_character.active = true;
            this._spine_character.opacity = 255
            // this._spine_character.getComponent(sp.Skeleton).setAnimation(0,"idle_base",false);
        }

        if(bFree && cc.vv.gameData.isSuperBonus()){
            this._bottomScript.SetBetNodeVisible(false)
        } else {
            this._bottomScript.SetBetNodeVisible(true)
        }
    },

    // update (dt) {},
});
