
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    //初始化公共组件
    InitCommComponent:function() {
        this._super();

        let script_collect = this.node.addComponent("Loki_Collect");
        script_collect.Init();
        cc.vv.gameData.setCollectScript(script_collect);

        let script_popup = this.node.addComponent("Loki_Popup");
        script_popup.Init();
        cc.vv.gameData.setPopupScript(script_popup);

        let script_bonus = this.node.addComponent("Loki_BonusGame");
        script_bonus.Init();
        cc.vv.gameData.setBonusScript(script_bonus);

        let script_free = this.node.addComponent("Loki_FreeGame");
        script_free.Init();
        cc.vv.gameData.setFreeScript(script_free);
    },




    // update (dt) {},
});
