
cc.Class({
    extends: cc.Component,

    properties: {
        _itemList:[],
        _curIdx:0,
    },

    // LIFE-CYCLE CALLBACKS:

    Init(){
        // this._character = cc.find("safe_node/character", this.node);

        this._node_items = cc.find("safe_node/slots/free_items", this.node);
        this._node_items.active = false;
        for (let i = 1; i <= 15; i++){
            let item = cc.find("list/item"+i, this._node_items);
            this._itemList[i] = item;
        }

        this._free_win = cc.find("safe_node/slots/free_win", this.node);
        this._free_win.active = false;

        this._free_tuowei = cc.find("safe_node/free_tuowei", this.node);
        this._free_tuowei.active = false;
        this._lbl_mult = cc.find("safe_node/slots/lbl_mult", this.node);
        this._lbl_mult.active = false;
    },

    sortItems(){
        let items = Global.copy(cc.vv.gameData.getBonusGame().bonusItems);
        items.sort((a,b)=>{
            return a.mult-b.mult;
        })

        cc.log(items);
        return items
    },

    initAllItems(){
        for (let i = 1; i < this._itemList.length; i++){
            let spr = cc.find("spr",this._itemList[i]);
            // spr.opacity = 255;
            spr.active = false;
            this.setItemSprOpacity(i, true);
            for (let idx = 0; idx < spr.childrenCount; idx++){
                spr.children[idx].active = false;
            }
        }
    },

    showAllItems(){
        let restFreeCnt = cc.vv.gameData.GetFreeTime();
        let allFreeCnt = cc.vv.gameData.GetTotalFree();


        let items = this.sortItems();
        this._curIdx = items.length-restFreeCnt+1;

        for (let i = 1; i < this._itemList.length; i++){
            cc.find("spr", this._itemList[i]).active = i <= items.length;
            if(i <= items.length){
                // this.showItem(i-1, true)

                if(i < this._curIdx){
                    this.initItem(i, items[i-1], true);
                } else {
                    this.initItem(i, items[i-1], false);
                }



            } else {
                this.initItem(i, false);
                // this.showItem(i-1, false)
            }

        }
    },

    initItem(idx, data, hasOpen){
        let item = this._itemList[idx];
        let spr = cc.find("spr", item);
        spr.active = data;
        if(data){
            let spr_di = cc.find("spr_di", spr);
            let lbl_win = cc.find("lbl_win", spr);
            let lbl_mult = cc.find("lbl_mult", spr);
            let anim_show = cc.find("anim_show", spr);
            let spr_xz1 = cc.find("spr_xz1", spr);
            let spr_xz2 = cc.find("spr_xz2", spr);

            if(hasOpen){
                if(data.coin > 0){
                    spr_di.active = true;
                    lbl_win.active = true;
                    lbl_win.getComponent(cc.Label).string = Global.convertNumToShort(data.coin,1000,0)
                }else {
                    // spr.opacity = 150;
                    this.setItemSprOpacity(idx, false)
                    lbl_mult.active = true;
                    lbl_mult.getComponent(cc.Label).string = data.mult+"X"
                }
            } else {
                // spr.opacity = 255;
                this.setItemSprOpacity(idx, true)
                lbl_mult.active = true;
                lbl_mult.getComponent(cc.Label).string = data.mult+"X"
            }
        }
    },

    setItemSprOpacity(idx, bShow){
        cc.find("spr", this._itemList[idx]).opacity = bShow?255:150;
    },

    showItem(idx, bShow, data){
        let item = this._itemList[idx];
        let spr = cc.find("spr", item);
        let anim_show = cc.find("anim_show", spr);
        let lbl_mult = cc.find("lbl_mult", spr);

        if(bShow){
            spr.active = true;
            spr.setScale(0);
            cc.tween(spr).to(0.5, {scale:1}, {easing:"backOut"}).start()

            anim_show.active = true;
            anim_show.getComponent(cc.Animation).play("free_itemShow");

            lbl_mult.active = true;
            lbl_mult.getComponent(cc.Label).string = data.mult+"X"
        }else {
            spr.active = false;
        }
    },

    playFreeWin(winCoin, roolTime){
        this._free_win.active = true;
        let lbl = cc.find("lbl", this._free_win);

        if(winCoin === 0){
            lbl.getComponent(cc.Label).string = winCoin
        } else {
            Global.doRoallNumEff(lbl,0,winCoin, roolTime,null,null,0,true);
        }
    },

    enterFreeGame(){
        return new Promise(async (success, failed)=> {
            // this._character.active = false;

            this._node_items.active = true;
            cc.vv.gameData.getCollectScript().setCollectNodeState(false);

            this.showAllItems();
            this.playFreeWin(0);

            success();
        });
    },

    async exitFreeGame(){
        return new Promise(async (success, failed)=> {
            await this.playFreeEnd();

            let winCoin = cc.vv.gameData.GetGameTotalFreeWin();
            await cc.vv.gameData.getPopupScript().showEndFree(winCoin);

            cc.vv.gameData.getBonusScript().resetJackpot();

            this._node_items.active = false;
            cc.vv.gameData.getCollectScript().setCollectNodeState(true);

            this._free_win.active = false;

            if (cc.vv.gameData.isSuperBonus()) {
                cc.vv.gameData.getBonusTrail().count = 0;
                cc.vv.gameData.getCollectScript().initItems();

                cc.vv.gameData.setIsSuperBonus(false);
            }

            cc.vv.gameData.GetSlotsScript().ShowGameview(false);
            // this._character.active = true;
            // this._character.getComponent(sp.Skeleton).setAnimation(0,"idle_base",false);


            await new Promise((success, failed) => {
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(winCoin, winCoin, true, success)
            });
            success();
        });
    },


    triFreeGame(){
        return new Promise(async (success, failed)=> {
            cc.vv.gameData.GetSlotsScript().ShowGameview(true);

            /*this.playFreeWin(0);
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_notice");
            this._character.getComponent(sp.Skeleton).setAnimation(0, "upReel", false);
            this._character.getComponent(sp.Skeleton).addAnimation(0, "down", false);

            let pos = this._node_items.position;
            this._node_items.position = cc.find("safe_node/slots/reels", this.node).position;

            await cc.vv.gameData.awaitTime(2);
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_chessboard_up");
            this._node_items.active = true;
            cc.tween(this._node_items).to(0.5, {position: pos}).start();*/

            this._curIdx = cc.vv.gameData.getBonusGame().bonusItems.length-cc.vv.gameData.GetFreeTime() +1;

            this.playFreeWin(0);
            this.initAllItems();

            await cc.vv.gameData.awaitTime(1.3);
            // this._character.active = false;

            // 飞图标
            await this.flyAllItems();

            cc.vv.gameData.getBonusScript().showNormalSlots();
            await cc.vv.gameData.getPopupScript().showTriFree(cc.vv.gameData.GetTotalFree());



            success();
        });
    },

    flyAllItems(){
        return new Promise(async (success, failed)=> {
            let items = this.sortItems();
            for (let i = 0; i < items.length; i++){
                let symbol = cc.vv.gameData.getBonusScript().GetSymbolByIdx(items[i].idx);

                let fromPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                let toPos = this._itemList[i+1].convertToWorldSpaceAR(cc.v2(0, 0));

                symbol.setSymbolMask(true);
                Global.SlotsSoundMgr.playEffect("sound_Atlantis_fly");
                await this.flyItem(fromPos, toPos)
                this.showItem(i+1, true,items[i]);

                await cc.vv.gameData.awaitTime(0.5);
            }

            success();
        })
    },

    flyItem(fromPos, toPos){
        return new Promise(async (success, failed)=> {

            let from = this._free_tuowei.parent.convertToNodeSpaceAR(fromPos);
            let to = this._free_tuowei.parent.convertToNodeSpaceAR(toPos);

            //设置缩放和角度
            let v = cc.v2(to.x, to.y).sub(cc.v2(from.x, from.y));
            let length = v.mag();
            let angle = v.signAngle(cc.v2(1, 0));
            this._free_tuowei.active = true;
            this._free_tuowei.position = from;
            this._free_tuowei.angle = -angle * cc.macro.DEG +180// +90;
            this._free_tuowei.scale = length / 400;

            //播放动画
            this._free_tuowei.getComponent(cc.Animation).play("free_tuowei");
            // this._free_tuowei.getComponent(cc.Animation).on("stop", ()=>{
            // })
            await cc.vv.gameData.awaitTime(0.6);
            this._free_tuowei.active = false;
            success();
        });
    },


    StartMove(){
        let item = this._itemList[this._curIdx];

        let spr_xz1 = cc.find("spr/spr_xz1", item);
        let spr_xz2 = cc.find("spr/spr_xz2", item);
        spr_xz1.active = true;
        spr_xz2.active = true;
        spr_xz1.getComponent(cc.Animation).play("free_xuanzhong");
        cc.tween(spr_xz2).repeatForever(cc.tween().by(0.8, {angle:-360}).call(()=>{spr_xz2.angle = spr_xz2.angle%360})).start();
    },

    async OnSpinEnd(){
        let item = this._itemList[this._curIdx];
        let spr = cc.find("spr", item);
        let spr_di = cc.find("spr_di", spr);
        let lbl_win = cc.find("lbl_win", spr);
        let lbl_mult = cc.find("lbl_mult", spr);
        let spr_xz1 = cc.find("spr_xz1", spr);
        let spr_xz2 = cc.find("spr_xz2", spr);

        let win = cc.vv.gameData.GetGameWin();
        if(win > 0){
            cc.vv.gameData.GetSlotsScript().ShowWinTrace();
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_jumpCoin1")
            this.playFreeWin(win, 0.6);

            await cc.vv.gameData.awaitTime(0.6);

            this._lbl_mult.getComponent(cc.Label).string = lbl_mult.getComponent(cc.Label).string;
            this._lbl_mult.position = this._lbl_mult.parent.convertToNodeSpaceAR(lbl_mult.convertToWorldSpaceAR(cc.v2(0,0)));
            this._lbl_mult.active = true;
            lbl_mult.active = false;

            Global.SlotsSoundMgr.playEffect("sound_Atlantis_fly_down")
            let endPos = this._lbl_mult.parent.convertToNodeSpaceAR(cc.find("lbl", this._free_win).convertToWorldSpaceAR(cc.v2(0,0)));
            cc.tween(this._lbl_mult).to(0.8, {position:endPos})
                .call(()=>{ this._lbl_mult.active = false;})
                .start();
            await cc.vv.gameData.awaitTime(0.8);
            Global.SlotsSoundMgr.playEffect("sound_Atlantis_jumpCoin2")
            let items = this.sortItems()
            this.playFreeWin(items[this._curIdx-1].coin, 0.6);
            await cc.vv.gameData.awaitTime(0.6);

            spr_xz1.active = false;
            spr_xz2.stopAllActions();
            spr_xz2.active = false;

            spr_di.active = true;
            lbl_win.active = true;
            lbl_win.getComponent(cc.Label).string = Global.convertNumToShort(items[this._curIdx-1].coin,1000,0)

        } else if(!cc.vv.gameData.isSuperBonus()){

            spr_xz1.active = false;
            spr_xz2.stopAllActions();
            spr_xz2.active = false;

            spr.opacity = 150;
        }

        await cc.vv.gameData.awaitTime(0.5);

        // 免费结束
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.exitFreeGame()
        }

        if(cc.vv.gameData.isSuperBonus()){
            if(win > 0){
                this._curIdx += 1;
            }
        } else {
            this._curIdx += 1;
        }

        cc.vv.gameData.GetSlotsScript().CanDoNextRound();
    },


    playFreeEnd(){
        return new Promise(async (success, failed)=> {
            let items = this.sortItems();
            let total = 0;
            for (let i = 0; i < items.length; i++){
                if(items[i].coin > 0){
                    let fromPos = this._itemList[i+1].convertToWorldSpaceAR(cc.v2(0, 0));
                    let toPos = cc.find("Canvas/safe_node/LMSlots_Bottom/winBg").convertToWorldSpaceAR(cc.v2(0, 0));

                    this.setItemSprOpacity(i+1,false)
                    Global.SlotsSoundMgr.playEffect("sound_Atlantis_fly_over_down");
                    await this.flyItem(fromPos, toPos);
                    total += items[i].coin;
                    cc.vv.gameData.GetBottomScript().SetWin(total)
                }
            }

            success();
        })
    },


    // update (dt) {},
});
